// 代表题 ML 2。分数升序排列，秩从 1 开始，完全相同的分数取平均秩。
// AUC = (正样本秩和 - nPos*(nPos+1)/2) / (nPos*nNeg)，即随机一正一负里正分更高的概率加同分概率的一半。
// 换题若分数越小越好，把比较方向反过来，或先取负号再调用。
static double auc(int[] y, double[] score) {
    if (y == null || score == null || y.length == 0 || y.length != score.length) throw new IllegalArgumentException("length");
    int n = y.length;
    for (int i = 0;
    i < n;
    i++) if ((y[i] != 0 && y[i] != 1) || !Double.isFinite(score[i])) throw new IllegalArgumentException("label/score");
    Integer[] idx = new Integer[n];
    for (int i = 0;
    i < n;
    i++) idx[i] = i;
    Arrays.sort(idx, (a, b) -> Double.compare(score[a], score[b]));
    double[] rank = new double[n];
    for (int i = 0;
    i < n;
    ) {
        int j = i;
        while (j + 1 < n && score[idx[j + 1]] == score[idx[i]]) j++;
        double avg = ((double) i + j + 2) / 2.0;
        for (int k = i;
        k <= j;
        k++) rank[idx[k]] = avg;
        i = j + 1;
    }
    double sumPos = 0;
    int nPos = 0, nNeg = 0;
    for (int i = 0;
    i < n;
    i++) {
        if (y[i] == 1) {
            sumPos += rank[i];
            nPos++;
        } else nNeg++;
    }
    if (nPos == 0 || nNeg == 0) throw new IllegalArgumentException("both classes required");
    return (sumPos - (double) nPos * (nPos + 1L) / 2.0) / ((double) nPos * nNeg);
}

// ML 3：二分类输入是概率。p 夹在 (eps,1-eps) 里，避免 log(0)。
static double binaryCrossEntropy(double y, double p) {
    double eps = 1e-12;
    double pc = Math.min(1 - eps, Math.max(eps, p));
    return -(y * Math.log(pc) + (1 - y) * Math.log(1 - pc));
}
// ML 3：多分类输入是未归一化 logits，y 是类别下标。
// log p_y = z_y - max - log Σ exp(z_j - max)，与先 softmax 再 -log 等价，但不会溢出。
static double softmaxCrossEntropy(double[] logits, int y) {
    double m = logits[0];
    for (int i = 1;
    i < logits.length;
    i++) m = Math.max(m, logits[i]);
    double sum = 0;
    for (double z : logits) sum += Math.exp(z - m);
    return -(logits[y] - m - Math.log(sum));
}
// ML 4：KL(p||q)=Σ p_i·ln(p_i/q_i)。p_i=0 的项按极限记 0，故直接跳过。
// q_i=0 且 p_i>0 时为 +∞，这里不吞掉，会得到 Infinity。KL(q||p) 只需对调两个参数。
static double kl(double[] p, double[] q) {
    double s = 0;
    for (int i = 0;
    i < p.length;
    i++) {
        if (p[i] == 0) continue;
        s += p[i] * (Math.log(p[i]) - Math.log(q[i]));
    }
    return s;
}

